def create_state(user_request, max_steps=5):

    return {
        "user_request": user_request,
        # The list of tasks generated by the planner.
        "tasks": [],
        "current_task": None,

        # The current step in the agent loop.
        "current_step": 0,
        # The maximum number of steps the agent can take before stopping.
        "max_steps": max_steps,

        # The list of actions taken by the agent to complete the tasks.
        "actions": [],

        
        # The list of observations made by the agent. after executing an action.
        "observations": [],
        
        # The list of results from executing actions.
        "results": [],

        # The list of memories retrieved from the memory module.
        "memories": [],

        # The final status after completing all tasks.
        "finished": False,
        # The final answer generated by the agent after completing all tasks.   
        "final_answer": ""
    }


## add Memory to the state
def add_memory(state, memory):
    state["memories"].append(memory)

## add Task to the state
def add_task(state, task):

    state["tasks"].append({
        "task": task,
        "status": "pending"
    })


## mark a task as completed in the state
def complete_task(state, task):

    # Normalize the task received from the planner.
    # This makes the comparison tolerant of:
    # "Generate password"
    # "generate password"
    # "generate_password"

    normalized_task = (
        task
        .strip()
        .lower()
        .replace("_", " ")
    )

    for item in state["tasks"]:

        normalized_existing_task = (
            item["task"]
            .strip()
            .lower()
            .replace("_", " ")
        )

        if normalized_existing_task == normalized_task:

            item["status"] = "completed"

            return True

    return False


## get the pending tasks from the state
def get_pending_tasks(state):

    return [
        item["task"]
        for item in state["tasks"]
        if item["status"] == "pending"
    ]

## Check if all tasks are completed
def all_tasks_completed(state):

    if not state["tasks"]:
        return False

    return all(
        item["status"] == "completed"
        for item in state["tasks"]
    )



## add an action to the state
def add_action(state, action):

    state["actions"].append(action)


## record an observation in the state
def record_observation(
    state,
    action,
    observation
):

    state["observations"].append({
        "step": state["current_step"],
        "action": action,
        "observation": observation
    })


### add a result to the state
def add_result(state, result):

    state["results"].append(result)

### Move to the next step in the state
def next_step(state):

    state["current_step"] += 1


## Check if the agent can continue based on the state
def can_continue(state):

    return (
        not state["finished"]
        and state["current_step"] < state["max_steps"]
    )

### Finish the agent loop and set the final answer in the state
def finish(state, answer):

    state["final_answer"] = answer
    state["finished"] = True